    ["SETTINGS_TITLE"] = "Moduleinstellungen",
    ["SETUP_WIZARD_AUDIO_FOCUS_BODY"] = "Senkt beim Angeln vorübergehend unwichtige Audiokanäle, damit Angelgeräusche leichter zu hören sind, und stellt danach deine vorherigen Audioeinstellungen wieder her.",
    ["SETUP_WIZARD_AUTO_LOOT_BODY"] = "Aktiviert Auto-Loot für Angelbeute vorübergehend und stellt danach deine vorherige WoW-Einstellung wieder her.",
    ["SETUP_WIZARD_BUTTON_BODY"] = "Eine kleinere Nur-Symbol-Steuerung für Spieler, die weniger Bildschirmplatz verwenden möchten.",
    ["SETUP_WIZARD_COMFORT_BODY"] = "Diese Optionen ändern, wie sich die Angelsteuerung beim Angeln vom Reittier, Schwimmen und Spielaudio verhält.",
    ["SETUP_WIZARD_COMFORT_TITLE"] = "Komfortoptionen",
    ["SETUP_WIZARD_DISMOUNT_BODY"] = "Fügt /dismount vor der Angelaktion ein, damit deine gewählte Eingabe beim Reiten mit dem Angeln beginnen kann.",
