    ["SETUP_WIZARD_HELPERS_TITLE"] = "Angelhilfen",
    ["SETUP_WIZARD_HIDE_TROPHY_BODY"] = "Blendet Trophäenfische aus der Midnight-Wertungsliste aus, wenn du dich auf normale Wertungsgewinne konzentrieren möchtest.",
    ["SETUP_WIZARD_HUD_BODY"] = "Empfohlen. Zeigt die nächste Angelaktion mit Symbol und kurzem Statustext, damit sie auf einen Blick leichter zu verstehen ist.",
    ["SETUP_WIZARD_INPUT_BODY"] = "Avid Angler kann die aktuelle Angelaktion auf eine Eingabe legen. Beim Angeln wechselt dieselbe Eingabe von Auswerfen zu Schwimmer-Interaktion und nach dem Loot zurück zu Auswerfen.",
    ["SETUP_WIZARD_INPUT_OFF_BODY"] = "Lässt Angelsteuerungen ausgeschaltet, bis du später Ein-Tasten oder Doppel-Rechtsklick aktivierst.",
    ["SETUP_WIZARD_INPUT_OFF_LABEL"] = "Keine Eingabebindung",
    ["SETUP_WIZARD_INPUT_TITLE"] = "Angel-Eingabe wählen",
    ["SETUP_WIZARD_KEEP_WATCH_BODY"] = "Die Wertungswache ist ein kleines Midnight-Fortschrittsfenster, das beim Angeln und nach Wertungsupdates erscheint. Es zeigt Wertungsfortschritt und nützliche Ziele; dies hält es sichtbar, statt es automatisch auszublenden.",
    ["SETUP_WIZARD_KEEP_WATCH_LABEL"] = "Wertungswache offen halten (empfohlen)",
    ["SETUP_WIZARD_MODULE_CASTING_BODY"] = "Angel-Eingabe, Hilfseinstellungen, Aktionsauswahl, sichtbare Steuerungen und Ausrüstungswechsel.",
    ["SETUP_WIZARD_MODULE_SCORING_BODY"] = "Midnight-Wertungskarten, Möglichkeiten, Trophäenfilter, Fortschrittswache und Wertungshinweise.",
