    ["SETUP_WIZARD_RELEASE_SWIMMING_BODY"] = "Gibt die Angelbindung beim Schwimmen frei, außer eine Wasserspielzeug-Aktion ist bereit.",
    ["SETUP_WIZARD_REOPEN"] = "Einrichtungsassistent",
    ["SETUP_WIZARD_REOPEN_TOOLTIP"] = "Öffnet den Ersteinrichtungsassistenten erneut.",
    ["SETUP_WIZARD_SETTINGS_BODY"] = "Nutze Einstellungen für Köderscans, Schwimmerauswahl, Aktionsslots, Audiofokus, Module und detaillierte Steuerungen.",
    ["SETUP_WIZARD_SETTINGS_LABEL"] = "Einstellungen später öffnen",
