    ["SETUP_WIZARD_SOFT_INTERACT_BODY"] = "Erlaubt Avid Angler, WoWs Soft-Interact-Hilfe vorübergehend zu erhöhen, damit der Schwimmer zuverlässiger interagiert werden kann.",
    ["SETUP_WIZARD_SOFT_INTERACT_LABEL"] = "Soft Interact verwalten",
    ["SETUP_WIZARD_TRACKING_BODY"] = "Fang-Tracking zeichnet Angelbeute und Würfe auf. Midnight-Wertung nutzt diese Fänge plus Journaldaten, um Wertungsfortschritt und nützliche Ziele zu zeigen.",
