    ["ACH_WAYPOINT_BUTTON"] = "Wegpunkt: %s (%.1f, %.1f)",
    ["ACH_WAYPOINT_TOOLTIP"] = "Setzt dieses Ziel in TomTom, falls verfügbar. Andernfalls werden Blizzards Kartenmarkierung und Zielnavigation verwendet.",
    ["ACH_WAYPOINT_TOMTOM_SET"] = "Wegpunkt zu TomTom hinzugefügt.",
